@Service
public class APIClientService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public APIClientService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new APIClientEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(APIClientRepository.class) );
		this.validator		= applicationContext.getBean(APIClientValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		APIClient
	 */
		public APIClient createAPIClient( CreateAPIClientCommand command ) {

		APIClient entity = new APIClient();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setAPIClientId( command.getAPIClientId() );
            entity.setName( command.getName() );
            entity.setClientId( command.getClientId() );
            entity.setRedirectUri( command.getRedirectUri() );
            entity.setClientType( command.getClientType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of APIClient {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateAPIClientCommand
	 * @return		APIClient
	 */
	public APIClient updateAPIClient( UpdateAPIClientCommand command ) {

		APIClient entity = new APIClient();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setAPIClientId( command.getAPIClientId() );
            entity.setName( command.getName() );
            entity.setClientId( command.getClientId() );
            entity.setRedirectUri( command.getRedirectUri() );
            entity.setConsents( command.getConsents() );
            entity.setClientType( command.getClientType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of APIClient {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteAPIClientCommand
	 */
	public void delete( DeleteAPIClientCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getAPIClientId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of APIClient {0} ", id );

	}

	/**
	 * Method to retrieve the APIClient via APIClientFetchOneSummary
	 * @param 	summary APIClientFetchOneSummary
	 * @return 	APIClientFetchOneResponse
	 */
	public APIClient getAPIClient( APIClientFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "APIClientFetchOneSummary arg cannot be null" );

		APIClient entity = null;
		UUID id = summary.getAPIClientId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a APIClient using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all APIClients
	 *
	 * @return 	List<APIClient>
	 */
    public List<APIClient> getAllAPIClient() {
		List<APIClient> list = projector.findAll( new FindAllAPIClientQuery() );
		return list;
	}


	/**
	 * add Consent to Consents
	 * @param		command AssignConsentsToAPIClientCommand
	 */
	public void addToConsents( AssignConsentsToAPIClientCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToConsents(command.getAPIClientId(), command.getAddTo());
	}

	/**
	 * remove Consent from Consents
	 * @param		command RemoveConsentsFromAPIClientCommand
	 */
	public void removeFromConsents( RemoveConsentsFromAPIClientCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromConsents(command.getAPIClientId(), command.getRemoveFrom());
	}




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final APIClientEntityProjector projector;
	private final APIClientValidator validator;
	private APIClient aPIClient 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(APIClientService.class);
}
